const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const houston = ee.Geometry.Point([-95.3698, 29.7604]); // Approximate center of Houston
  const scale = 5000; // Use a reasonable scale to avoid memory issues and represent a city area

  // Date ranges
  const dec2012_start = '2012-12-01';
  const dec2012_end = '2013-01-01';
  const dec2013_start = '2013-12-01';
  const dec2013_end = '2014-01-01';
  const other_months_start = '2012-01-01';
  const other_months_end = '2015-01-01'; // Up to end of 2014

  const NTL_COLLECTION = 'NOAA/DMSP-OLS/NIGHTTIME_LIGHTS';
  const NTL_BAND = 'stable_lights';

  // Function to get image collection for a period and check its size
  const getCollectionAndCheck = async (startDate, endDate, name) => {
    const collection = ee.ImageCollection(NTL_COLLECTION)
      .filterBounds(houston)
      .filterDate(startDate, endDate)
      .select(NTL_BAND);

    const size = await collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for ${name} (${startDate} - ${endDate}).`);
      return { collection: null, size: 0 };
    }
    return { collection: collection, size: size };
  };

  // 2. Data Acquisition & Check for Dec 2012
  const dec2012_info = await getCollectionAndCheck(dec2012_start, dec2012_end, "Dec 2012");
  if (dec2012_info.size === 0) {
    console.log("Empty collection for Dec 2012.");
    console.log("C1");
    return;
  }
  const dec2012_img = dec2012_info.collection.mean().clip(houston);

  // Data Acquisition & Check for Dec 2013
  const dec2013_info = await getCollectionAndCheck(dec2013_start, dec2013_end, "Dec 2013");
  if (dec2013_info.size === 0) {
    console.log("Empty collection for Dec 2013.");
    console.log("C1");
    return;
  }
  const dec2013_img = dec2013_info.collection.mean().clip(houston);

  // Data Acquisition & Check for other months (2012-2014 excluding Dec 2012 and Dec 2013)
  let other_months_collection = ee.ImageCollection(NTL_COLLECTION)
    .filterBounds(houston)
    .filterDate(other_months_start, other_months_end)
    .select(NTL_BAND);

  // Filter out Dec 2012 and Dec 2013
  other_months_collection = other_months_collection.filter(
    ee.Filter.not(ee.Filter.date(dec2012_start, dec2012_end))
  ).filter(
    ee.Filter.not(ee.Filter.date(dec2013_start, dec2013_end))
  );

  const other_months_size = await other_months_collection.size().getInfo();
  if (other_months_size === 0) {
    console.log("No images found for 'Other Months' (2012-2014, excluding Dec 2012/2013).");
    console.log("C1");
    return;
  }
  const other_months_img = other_months_collection.mean().clip(houston);

  console.log(`Dec 2012 Images: ${dec2012_info.size}`);
  console.log(`Dec 2013 Images: ${dec2013_info.size}`);
  console.log(`Other Months Images: ${other_months_size}`);

  // 3. Processing & Calculation
  const reducer = ee.Reducer.mean();

  const getMeanLight = async (image, name) => {
    const result = await image.reduceRegion({
      reducer: reducer,
      geometry: houston,
      scale: scale,
      maxPixels: 1e9,
    }).get(NTL_BAND).getInfo();

    const pixel_count = await image.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: houston,
      scale: scale,
      maxPixels: 1e9,
    }).get(NTL_BAND).getInfo();

    if (pixel_count === 0) {
      console.log(`No valid pixels for ${name} after clipping/masking.`);
      return { value: null, pixels: 0 };
    }
    return { value: result, pixels: pixel_count };
  };

  const dec2012_lights = await getMeanLight(dec2012_img, "Dec 2012");
  const dec2013_lights = await getMeanLight(dec2013_img, "Dec 2013");
  const other_months_lights = await getMeanLight(other_months_img, "Other Months");

  if (dec2012_lights.pixels === 0 || dec2013_lights.pixels === 0 || other_months_lights.pixels === 0) {
    console.log("C2");
    return;
  }

  // 4. Validation & Final Answer
  if (dec2012_lights.value === null || dec2013_lights.value === null || other_months_lights.value === null) {
    console.log("Calculation resulted in None/NaN for one or more periods.");
    console.log("C3");
    return;
  }

  const avg_dec_lights = (dec2012_lights.value + dec2013_lights.value) / 2;

  console.log(`Dec 2012 Avg Light: ${dec2012_lights.value.toFixed(2)} (Pixels: ${dec2012_lights.pixels})`);
  console.log(`Dec 2013 Avg Light: ${dec2013_lights.value.toFixed(2)} (Pixels: ${dec2013_lights.pixels})`);
  console.log(`Other Months Avg Light: ${other_months_lights.value.toFixed(2)} (Pixels: ${other_months_lights.pixels})`);
  console.log(`Average Dec Lights (2012 & 2013): ${avg_dec_lights.toFixed(2)}`);

  if (avg_dec_lights > other_months_lights.value) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
